def _call_authorization(service, supplied, resource):
    try:
        reply = service.authenticate(supplied, resource)
    except RuntimeError:
        return {"state": "unavailable"}
    if reply["authorized"]:
        return {"state": "authorized", "reply": reply}
    return {"state": "denied"}


